        setPendingBranchSwitch(null);
      }
      setLastDetectedBranch(detectedBranch);
      return;
    }
    if (pendingBranchSwitch && homeBranch && sameBranchRef(detectedBranch, homeBranch)) {
      setPendingBranchSwitch(null);
