 77	/**
 78	 * Resolves git provenance required by worker review creation.
 79	 * Falls back to GITHUB_HEAD_REF when local branch detection is unavailable (for CI detached-head runs).
 80	 */
 81	export function resolveReviewGitProvenance(cwd = process.cwd()): { repo: string; branch: string } {
 82	  let branchCandidate = '';
 83	  try {
 84	    branchCandidate = new GitRepo(cwd).getCurrentBranchRef() ?? '';
 85	  } catch (error) {
 86	    const details = error instanceof Error ? error.message : String(error);
 87	    throw new Error(`Could not resolve current git branch: ${details}`);
 88	  }
 89	
 90	  let branch = normalizeBranchRefForProvenance(branchCandidate);
 91	
 92	  if (!branch) {
 93	    const githubHeadRef = typeof process.env.GITHUB_HEAD_REF === 'string' ? process.env.GITHUB_HEAD_REF.trim() : '';
 94	    if (githubHeadRef) {
 95	      branch = normalizeBranchRefForProvenance(githubHeadRef);
 96	      if (!branch) {
 97	        throw new Error(`GITHUB_HEAD_REF is present but invalid for branch provenance: ${githubHeadRef}`);
 98	      }
 99	    }
100	  }
101	
102	  if (!branch) {
103	    throw new Error(
104	      'Could not resolve current git branch (git branch detection failed and GITHUB_HEAD_REF not set). In GitHub Actions, ensure GITHUB_HEAD_REF is available in the workflow environment.'
105	    );
106	  }
107	
108	  let repo = '';
109	  try {
110	    repo = detectRepoSlugFromGitOrigin(cwd);
111	  } catch (error) {
112	    const details = error instanceof Error ? error.message : String(error);
113	    throw new Error(`Could not resolve git repo slug from origin: ${details}`);
114	  }
115	
116	  return { repo: repo.trim(), branch };
117	}
