119	export function buildStudioReviewRoutePath(options: {
120	  reviewId: string;
121	  route: 'policy' | 'reports';
122	  repo?: string | null;
123	  branch?: string | null;
124	}): string {
125	  const reviewId = encodeURIComponent(options.reviewId);
126	  const repo = options.repo?.trim();
127	  const branch = options.branch?.trim();
128	
129	  if (repo && branch) {
130	    return `/branches/${encodeURIComponent(repo)}/${encodeURIComponent(branch)}/${options.route}/${reviewId}`;
131	  }
132	
133	  return `/${options.route}/${reviewId}`;
134	}
